-- India milestone translations (ES/DE/FR)

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-gst-council-2019', 'es', 'El Consejo del GST aprueba la facturación electrónica B2B por fases', 'La decisión política que pone todo lo demás en marcha, seguida de una ventana de adopción voluntaria a partir de enero de 2020.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-gst-council-2019', 'de', 'Der GST-Rat genehmigt die stufenweise B2B-E-Rechnungsstellung', 'Die politische Entscheidung, die alles Weitere in Gang setzt, gefolgt von einem freiwilligen Einführungsfenster ab Januar 2020.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-gst-council-2019', 'fr', 'Le Conseil du GST approuve la facturation électronique B2B par étapes', 'La décision politique qui met tout le reste en mouvement, suivie d''une fenêtre d''adoption volontaire à partir de janvier 2020.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-500cr-2020', 'es', 'Comienza la facturación electrónica obligatoria — facturación ≥ ₹500 crore', 'Los mayores contribuyentes se convierten en el primer grupo obligado a reportar facturas a un Portal de Registro de Facturas (IRP) y obtener un IRN válido.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-500cr-2020', 'de', 'Verpflichtende E-Rechnungsstellung beginnt — Umsatz ≥ ₹500 Crore', 'Die größten Steuerpflichtigen werden die erste Kohorte, die Rechnungen an ein Invoice Registration Portal (IRP) melden und eine gültige IRN erhalten muss.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-500cr-2020', 'fr', 'La facturation électronique obligatoire commence — chiffre d''affaires ≥ ₹500 crore', 'Les plus grands contribuables deviennent la première cohorte tenue de déclarer les factures à un portail d''enregistrement des factures (IRP) et d''obtenir un IRN valide.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-threshold-reductions', 'es', 'El umbral desciende a través de notificaciones sucesivas', 'El límite de facturación baja por etapas a lo largo de 2021–2023, incorporando progresivamente a empresas más pequeñas dentro del alcance con cada reducción.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-threshold-reductions', 'de', 'Die Schwelle sinkt durch aufeinanderfolgende Bekanntmachungen', 'Die Umsatzgrenze sinkt schrittweise über 2021–2023 hinweg und bringt mit jeder Reduzierung zunehmend kleinere Unternehmen in den Anwendungsbereich.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-threshold-reductions', 'fr', 'Le seuil baisse par le biais de notifications successives', 'Le seuil de chiffre d''affaires diminue par étapes au cours de 2021–2023, faisant entrer progressivement des entreprises plus petites dans le champ d''application à chaque réduction.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-2fa-2023', 'es', 'Autenticación de dos factores obligatoria para grandes contribuyentes', 'La autenticación de dos factores se vuelve obligatoria en el portal del GST para contribuyentes con AATO superior a ₹100 crore, reforzando la seguridad de acceso antes de nuevas reducciones del umbral.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-2fa-2023', 'de', 'Zwei-Faktor-Authentifizierung für große Steuerpflichtige verpflichtend', 'Die Zwei-Faktor-Authentifizierung wird auf dem GST-Portal für Steuerpflichtige mit einem AATO über ₹100 Crore verpflichtend und verschärft die Zugangssicherheit vor weiteren Schwellenreduzierungen.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-2fa-2023', 'fr', 'Authentification à deux facteurs obligatoire pour les grands contribuables', 'L''authentification à deux facteurs devient obligatoire sur le portail GST pour les contribuables dont l''AATO dépasse ₹100 crore, renforçant la sécurité d''accès avant de nouvelles réductions de seuil.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-threshold', 'es', 'Facturación electrónica GST obligatoria por encima de ₹5 crore de facturación (en vigor desde agosto de 2023)', 'Cualquier empresa registrada en el GST con una facturación anual agregada (AATO) superior a ₹5 crore en cualquier ejercicio fiscal desde 2017–18 debe generar facturas electrónicas con un IRN válido para transacciones B2B y de exportación.', '["Confirme la facturación agregada en todos los GSTIN bajo su PAN — solo necesita superar ₹5 crore una vez", "Regístrese en un Portal de Registro de Facturas (IRP) — einvoice1.gst.gov.in del NIC o un IRP privado autorizado", "Esté atento a una posible reducción del umbral a ₹2 crore, en discusión pero aún no notificada"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-threshold', 'de', 'GST-E-Rechnungsstellung ab einem Umsatz von ₹5 Crore verpflichtend (in Kraft seit August 2023)', 'Jedes GST-registrierte Unternehmen mit einem aggregierten Jahresumsatz (AATO) von über ₹5 Crore in einem Geschäftsjahr seit 2017–18 muss E-Rechnungen mit einer gültigen IRN für B2B- und Exporttransaktionen erstellen.', '["Bestätigen Sie den aggregierten Umsatz über alle GSTINs unter Ihrer PAN — er muss nur einmal ₹5 Crore überschreiten", "Registrieren Sie sich bei einem Invoice Registration Portal (IRP) — einvoice1.gst.gov.in des NIC oder einem autorisierten privaten IRP", "Achten Sie auf eine mögliche Schwellenreduzierung auf ₹2 Crore, die diskutiert, aber noch nicht bekannt gegeben wurde"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-threshold', 'fr', 'Facturation électronique GST obligatoire au-delà de ₹5 crore de chiffre d''affaires (en vigueur depuis août 2023)', 'Toute entreprise enregistrée à la GST dont le chiffre d''affaires annuel agrégé (AATO) dépasse ₹5 crore au cours d''un exercice fiscal depuis 2017–18 doit générer des factures électroniques avec un IRN valide pour les transactions B2B et d''exportation.', '["Confirmez le chiffre d''affaires agrégé sur tous les GSTIN sous votre PAN — il ne doit dépasser ₹5 crore qu''une seule fois", "Inscrivez-vous auprès d''un portail d''enregistrement des factures (IRP) — einvoice1.gst.gov.in du NIC ou un IRP privé autorisé", "Surveillez une éventuelle réduction du seuil à ₹2 crore, en discussion mais pas encore notifiée"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-30day', 'es', 'Ventana de reporte de IRN de 30 días (AATO ≥ ₹10 crore)', 'Las facturas, notas de crédito y notas de débito de más de 30 días ya no pueden reportarse al IRP para la generación de IRN — serán rechazadas directamente para contribuyentes con AATO de ₹10 crore o más.', '["Integre la ventana de reporte de 30 días en su flujo de trabajo de cuentas por pagar/cobrar", "Active la autenticación multifactor en el portal del GST — obligatoria desde abril de 2025"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-30day', 'de', '30-Tage-IRN-Meldefenster (AATO ≥ ₹10 Crore)', 'Rechnungen, Gutschriften und Lastschriften, die älter als 30 Tage sind, können nicht mehr zur IRN-Generierung an das IRP gemeldet werden — sie werden für Steuerpflichtige mit einem AATO von ₹10 Crore oder mehr komplett abgelehnt.', '["Integrieren Sie das 30-Tage-Meldefenster in Ihren Kreditoren-/Debitorenworkflow", "Aktivieren Sie die Multi-Faktor-Authentifizierung auf dem GST-Portal — verpflichtend seit April 2025"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-30day', 'fr', 'Fenêtre de déclaration IRN de 30 jours (AATO ≥ ₹10 crore)', 'Les factures, notes de crédit et notes de débit de plus de 30 jours ne peuvent plus être déclarées à l''IRP pour la génération d''IRN — elles seront rejetées d''emblée pour les contribuables dont l''AATO est de ₹10 crore ou plus.', '["Intégrez la fenêtre de déclaration de 30 jours dans votre flux de travail comptes fournisseurs/clients", "Activez l''authentification multifacteur sur le portail GST — obligatoire depuis avril 2025"]');
